struct output {uint32_t hash;unsigned packets,short_write;FILE *file;};
static ssize_t output(void *v,const void *data,size_t n){struct output *o=v;const unsigned char *p=data;size_t i;if(n!=188||p[0]!=0x47)return -1;if(o->short_write)return 187;if(o->file&&fwrite(p,1,n,o->file)!=n)return -1;for(i=0;i<n;i++)o->hash=(o->hash^p[i])*16777619u;o->packets++;return n;}
static int self_test(void){struct live_mux m;struct output o={2166136261u,0,0,0};unsigned char au[]={0,0,1,0x67,0x42,0x80,0x1f,0,0,1,0x68,0xee,0,0,1,0x65,0x88,0x84},pred[]={0,0,1,0x41,0x9a,0x21};unsigned count;live_mux_init(&m,output,&o);if(live_mux_push(&m,pred,sizeof(pred),8,0)||o.packets)return 1;if(live_mux_push(&m,au,sizeof(au),31,0)!=1||live_mux_tick(&m,32)||live_mux_push(&m,pred,sizeof(pred),8,64)!=1)return 2;if(o.hash!=229488962u)return 3;count=o.packets;if(live_mux_push(&m,pred,sizeof(pred),8,63)!=-1||!m.failed||o.packets!=count)return 4;if(live_mux_tick(&m,65)!=-1||o.packets!=count)return 5;live_mux_init(&m,output,&o);o.short_write=1;if(live_mux_push(&m,au,sizeof(au),31,0)!=-1||!m.failed)return 6;o.short_write=0;live_mux_init(&m,output,&o);if(live_mux_push(&m,au,sizeof(au),8,0)!=-1)return 7;live_mux_init(&m,output,&o);if(live_mux_push(&m,au,LIVE_AU_LIMIT+1,31,0)!=-1)return 8;puts("LIVE_MUX_QNX_PASS native_psi=1 golden_byte_identity=1 independent_frame_gate=1 timestamps=1 bounds=1 short_write_fail_closed=1");return 0;}
static uint32_t word(const unsigned char *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
int main(int argc,char **argv){static unsigned char au[LIVE_AU_LIMIT];unsigned char h[16];struct live_mux m;struct output o={2166136261u,0,0,0};FILE *in;uint64_t tick=0;if(argc==1)return self_test();if(argc!=3)return 9;in=fopen(argv[1],"rb");o.file=fopen(argv[2],"wb");if(!in||!o.file)return 10;live_mux_init(&m,output,&o);for(;;){uint32_t n,flags;uint64_t ms;size_t count=fread(h,1,16,in);if(!count)break;if(count!=16)return 11;ms=word(h)|(uint64_t)word(h+4)<<32;n=word(h+8);flags=word(h+12);if(!n||n>LIVE_AU_LIMIT||fread(au,1,n,in)!=n)return 12;while(tick<ms){if(live_mux_tick(&m,tick))return 13;tick+=32;}if(live_mux_push(&m,au,n,flags,ms)!=1)return 14;}if(ferror(in)||fclose(in)||fclose(o.file))return 15;return 0;}
